/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMono } = loadRobotoMono();



export type TradingChartProps = Record<string, any>;

// Deterministic mock data for the chart
const CHART_DATA = [
  { open: 30, close: 45, high: 50, low: 25 },
  { open: 45, close: 40, high: 55, low: 35 },
  { open: 40, close: 60, high: 65, low: 35 },
  { open: 60, close: 50, high: 70, low: 45 }, // Entry point near here
  { open: 50, close: 80, high: 85, low: 45 },
  { open: 80, close: 75, high: 90, low: 70 },
  { open: 75, close: 95, high: 100, low: 70 },
  { open: 95, close: 85, high: 105, low: 80 },
  { open: 85, close: 110, high: 120, low: 80 },
  { open: 110, close: 100, high: 115, low: 95 },
  { open: 100, close: 135, high: 145, low: 90 }, // Exit point near here
  { open: 135, close: 125, high: 150, low: 115 },
];

const MIN_VAL = 10;
const MAX_VAL = 160;
const RANGE = MAX_VAL - MIN_VAL;

const ENTRY_IDX = 3;
const EXIT_IDX = 10;
const STOP_LOSS_VAL = 35;

const TradingChart: React.FC<TradingChartProps> = ({
  backgroundColor = "#0a192f",
  transparentBackground = false,
  durationInSeconds = 6,
  chartType = "Candlestick",
  entryColor = "#00ff88",
  exitColor = "#00b8ff",
  stopLossColor = "#ff3366",
  glowIntensity = 0.8,
  title = "BTC/USD PERP",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const chartW = width * 0.85;
  const chartH = height * 0.5;

  // Animations
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const chartRevealProgress = interpolate(
    frame,
    [30, 120],
    [0, 1],
    { extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) }
  );

  const markerEntryScale = spring({
    frame: frame - 100,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  const markerExitScale = spring({
    frame: frame - 130,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  const stopLossReveal = interpolate(
    frame,
    [90, 120],
    [0, chartW],
    { extrapolateRight: "clamp", easing: Easing.out(Easing.ease) }
  );

  // 3D Perspective rotation (subtle constant motion)
  const rotateX = interpolate(frame, [0, durationInSeconds * fps], [25, 15]);
  const rotateZ = interpolate(frame, [0, durationInSeconds * fps], [5, -2]);
  const scale = interpolate(entranceSpring, [0, 1], [0.8, 1]);

  // Generate Path Data for Line/Area
  const points = CHART_DATA.map((d, i) => {
    const x = (i / (CHART_DATA.length - 1)) * chartW;
    const y = chartH - ((d.close - MIN_VAL) / RANGE) * chartH;
    return { x, y };
  });
  const pathD = `M ${points.map((p) => `${p.x},${p.y}`).join(" L ")}`;
  const areaD = `${pathD} L ${chartW},${chartH} L 0,${chartH} Z`;

  // Pre-calculate Marker Positions
  const entryX = (ENTRY_IDX / (CHART_DATA.length - 1)) * chartW;
  const entryY = chartH - ((CHART_DATA[ENTRY_IDX].low - MIN_VAL) / RANGE) * chartH + 30;

  const exitX = (EXIT_IDX / (CHART_DATA.length - 1)) * chartW;
  const exitY = chartH - ((CHART_DATA[EXIT_IDX].high - MIN_VAL) / RANGE) * chartH - 30;

  const stopLossY = chartH - ((STOP_LOSS_VAL - MIN_VAL) / RANGE) * chartH;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: robotoMono,
        color: "#ffffff",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        perspective: "1200px",
        transition: "none",
      }}
    >
      {/* Background Grid */}
      <div
        style={{
          position: "absolute",
          width: "200%",
          height: "200%",
          backgroundImage: `
            linear-gradient(rgba(255,255,255,0.03) 2px, transparent 2px),
            linear-gradient(90deg, rgba(255,255,255,0.03) 2px, transparent 2px)
          `,
          backgroundSize: "60px 60px",
          backgroundPosition: "center center",
          transform: `translateZ(-500px) rotateX(20deg) translateY(${-(frame * 0.5) % 60}px)`,
          opacity: entranceSpring,
          transition: "none",
        }}
      />

      {/* Main 3D Container */}
      <div
        style={{
          width: chartW,
          height: chartH,
          transformStyle: "preserve-3d",
          transform: `scale(${scale}) rotateX(${rotateX}deg) rotateZ(${rotateZ}deg)`,
          transition: "none",
          position: "relative",
        }}
      >
        {/* UI Header */}
        <div
          style={{
            position: "absolute",
            top: -80,
            left: 0,
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-end",
            opacity: entranceSpring,
            transform: "translateZ(20px)",
            transition: "none",
          }}
        >
          <div>
            <div style={{ fontSize: 36, fontWeight: "bold", letterSpacing: "2px" }}>
              {title}
            </div>
            <div style={{ fontSize: 20, color: "rgba(255,255,255,0.5)", marginTop: 8 }}>
              TICK INTERVAL: 15M
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div
              style={{
                width: 12,
                height: 12,
                borderRadius: "50%",
                backgroundColor: "#ff3366",
                opacity: Math.sin(frame * 0.2) > 0 ? 1 : 0.2,
                boxShadow: `0 0 10px #ff3366`,
                transition: "none",
              }}
            />
            <span style={{ fontSize: 24, fontWeight: "bold" }}>LIVE</span>
          </div>
        </div>

        {/* SVG Chart Layer */}
        <svg
          width={chartW}
          height={chartH}
          style={{
            overflow: "visible",
            transform: "translateZ(10px)",
            filter: `drop-shadow(0px 10px 30px rgba(0,0,0,0.5))`,
            transition: "none",
          }}
        >
          <defs>
            <clipPath id="reveal-clip">
              <rect x={0} y={-100} width={chartW * chartRevealProgress} height={chartH + 200} />
            </clipPath>
            <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#ffffff" stopOpacity={0.4} />
              <stop offset="100%" stopColor="#ffffff" stopOpacity={0.0} />
            </linearGradient>
            
            {/* Glow Filters */}
            <filter id="glow-entry" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation={10 * glowIntensity} result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
            <filter id="glow-exit" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation={10 * glowIntensity} result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
            <filter id="glow-stop" x="-10%" y="-500%" width="120%" height="1000%">
              <feGaussianBlur stdDeviation={6 * glowIntensity} result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Grid lines inside chart */}
          {[0.25, 0.5, 0.75].map((ratio) => (
            <line
              key={`grid-${ratio}`}
              x1={0}
              y1={chartH * ratio}
              x2={chartW}
              y2={chartH * ratio}
              stroke="rgba(255,255,255,0.1)"
              strokeDasharray="4 4"
            />
          ))}

          {/* Chart Data Rendered with Reveal Clip */}
          <g clipPath="url(#reveal-clip)">
            {/* Area Chart */}
            {chartType === "Area" && (
              <path d={areaD} fill="url(#area-gradient)" />
            )}

            {/* Line / Area Top Stroke */}
            {(chartType === "Line" || chartType === "Area") && (
              <path
                d={pathD}
                fill="none"
                stroke="#ffffff"
                strokeWidth={4}
                style={{
                  filter: `drop-shadow(0px 0px ${10 * glowIntensity}px rgba(255,255,255,0.8))`,
                }}
              />
            )}

            {/* Candlestick Chart */}
            {chartType === "Candlestick" &&
              CHART_DATA.map((d, i) => {
                const x = (i / (CHART_DATA.length - 1)) * chartW;
                const candleW = Math.max(chartW * 0.04, 4);
                const isUp = d.close >= d.open;
                
                // Tech aesthetic: White/Cyan for up, Dark/Translucent for down
                const color = isUp ? "#ffffff" : "rgba(255,255,255,0.2)";
                const strokeColor = isUp ? "#ffffff" : "rgba(255,255,255,0.5)";

                const yHigh = chartH - ((d.high - MIN_VAL) / RANGE) * chartH;
                const yLow = chartH - ((d.low - MIN_VAL) / RANGE) * chartH;
                const yOpen = chartH - ((d.open - MIN_VAL) / RANGE) * chartH;
                const yClose = chartH - ((d.close - MIN_VAL) / RANGE) * chartH;

                const boxTop = Math.min(yOpen, yClose);
                const boxH = Math.max(Math.abs(yOpen - yClose), 2);

                return (
                  <g key={i} transform={`translate(${x}, 0)`}>
                    <line
                      x1={0}
                      y1={yHigh}
                      x2={0}
                      y2={yLow}
                      stroke={strokeColor}
                      strokeWidth={2}
                    />
                    <rect
                      x={-candleW / 2}
                      y={boxTop}
                      width={candleW}
                      height={boxH}
                      fill={color}
                      stroke={strokeColor}
                      strokeWidth={1}
                      style={
                        isUp
                          ? { filter: `drop-shadow(0px 0px ${8 * glowIntensity}px rgba(255,255,255,0.6))` }
                          : {}
                      }
                    />
                  </g>
                );
              })}
          </g>

          {/* Stop Loss Line */}
          <g>
            <line
              x1={0}
              y1={stopLossY}
              x2={stopLossReveal}
              y2={stopLossY}
              stroke={stopLossColor}
              strokeWidth={3}
              strokeDasharray="12 12"
              filter="url(#glow-stop)"
            />
            {stopLossReveal > 50 && (
              <text
                x={stopLossReveal - 10}
                y={stopLossY - 12}
                fill={stopLossColor}
                fontSize={16}
                fontWeight="bold"
                textAnchor="end"
                style={{ filter: "url(#glow-stop)" }}
              >
                STOP LOSS
              </text>
            )}
          </g>

          {/* Entry Marker */}
          <g
            transform={`translate(${entryX}, ${entryY}) scale(${markerEntryScale})`}
            style={{ transition: "none" }}
          >
            <circle
              cx={0}
              cy={0}
              r={12}
              fill="transparent"
              stroke={entryColor}
              strokeWidth={4}
              filter="url(#glow-entry)"
            />
            <circle cx={0} cy={0} r={4} fill={entryColor} filter="url(#glow-entry)" />
            <path d={`M 0,-15 L 0,-40`} stroke={entryColor} strokeWidth={2} strokeDasharray="4 4" />
            <text
              x={0}
              y={-48}
              fill={entryColor}
              fontSize={18}
              fontWeight="bold"
              textAnchor="middle"
              filter="url(#glow-entry)"
            >
              ENTRY
            </text>
          </g>

          {/* Exit Marker */}
          <g
            transform={`translate(${exitX}, ${exitY}) scale(${markerExitScale})`}
            style={{ transition: "none" }}
          >
            <circle
              cx={0}
              cy={0}
              r={12}
              fill="transparent"
              stroke={exitColor}
              strokeWidth={4}
              filter="url(#glow-exit)"
            />
            <circle cx={0} cy={0} r={4} fill={exitColor} filter="url(#glow-exit)" />
            <path d={`M 0,15 L 0,40`} stroke={exitColor} strokeWidth={2} strokeDasharray="4 4" />
            <text
              x={0}
              y={58}
              fill={exitColor}
              fontSize={18}
              fontWeight="bold"
              textAnchor="middle"
              filter="url(#glow-exit)"
            >
              EXIT
            </text>
          </g>
        </svg>
        
        {/* Bottom decorative HUD line */}
        <div
          style={{
            position: "absolute",
            bottom: -60,
            left: 0,
            width: "100%",
            height: 2,
            background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.5) 50%, rgba(255,255,255,0) 100%)",
            opacity: entranceSpring,
            transform: "translateZ(10px)",
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TradingChart;